cd /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-tmp-c0bapcfu/uitest/BskyNav && cat > Tests/NavTests.swift <<'EOF'
import XCTest

final class NavTests: XCTestCase {
    func testOpenAppearance() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        let openBtn = springboard.buttons["Open"]
        if openBtn.waitForExistence(timeout: 3) { openBtn.tap() }
        sleep(2)
        if !app.staticTexts["Appearance"].exists && !app.links["Appearance"].exists {
            let back = app.buttons["Go back"]
            _ = back.exists
        }
        let appearance = app.links["Appearance"]
        if appearance.waitForExistence(timeout: 5) {
            appearance.tap()
        } else {
            let settings = app.buttons["menuItemButton-Settings"]
            if settings.waitForExistence(timeout: 3) { settings.tap() }
            XCTAssertTrue(app.links["Appearance"].waitForExistence(timeout: 5))
            app.links["Appearance"].tap()
        }
        sleep(2)
        print("HIERARCHY_START")
        print(app.debugDescription)
        print("HIERARCHY_END")
    }
}
EOF
xcodebuild test -project BskyNav.xcodeproj -scheme BskyNavUITests -destination 'platform=iOS Simulator,id=0A7BB390-EF6E-476E-ADC0-EE9EB2680EB7' -only-testing:BskyNavUITests/NavTests/testOpenAppearance > run2.log 2>&1; echo exit $?; grep -E "error:|passed|failed" run2.log | head; sed -n '/HIERARCHY_START/,/HIERARCHY_END/p' run2.log | grep -E "label:" | grep -E "StaticText|Button|Switch|Link|Radio|Header|Heading|Picker|Option" | awk '{$1=$1};1' | head -60

